    public DbSet<PollingCenter> Centers=>Set<PollingCenter>();public DbSet<Booth> Booths=>Set<Booth>();public DbSet<ElectionCenter> ElectionCenters=>Set<ElectionCenter>();public DbSet<AgentAssignment> AgentAssignments=>Set<AgentAssignment>();public DbSet<CenterVerification> CenterVerifications=>Set<CenterVerification>();public DbSet<BoothAgent> BoothAgents=>Set<BoothAgent>();public DbSet<Voter> Voters=>Set<Voter>();public DbSet<Incident> Incidents=>Set<Incident>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.HasDefaultSchema("polling");
        var center=modelBuilder.Entity<PollingCenter>();center.ToTable("centers");center.HasKey(x=>x.Id);center.Property(x=>x.Id).HasColumnName("center_id");center.Property(x=>x.AreaId).HasColumnName("area_id");center.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50);center.Property(x=>x.Name).HasColumnName("name").HasMaxLength(250);center.Property(x=>x.Address).HasColumnName("address").HasMaxLength(500);center.Property(x=>x.CreatedAtUtc).HasColumnName("created_at");center.HasIndex(x=>new{x.AreaId,x.Code}).IsUnique();
