        var vt=modelBuilder.Entity<Voter>();vt.ToTable("voters");vt.HasKey(x=>x.Id);vt.Property(x=>x.Id).HasColumnName("voter_id");vt.Property(x=>x.TenantId).HasColumnName("tenant_id");vt.Property(x=>x.ElectionId).HasColumnName("election_id");vt.Property(x=>x.CenterId).HasColumnName("center_id");vt.Property(x=>x.BoothId).HasColumnName("booth_id");vt.Property(x=>x.CandidateId).HasColumnName("candidate_id");vt.Property(x=>x.VoterNumber).HasColumnName("voter_number").HasMaxLength(50);vt.Property(x=>x.SerialNumber).HasColumnName("serial_number");vt.Property(x=>x.FullName).HasColumnName("full_name").HasMaxLength(150);vt.Property(x=>x.FatherOrSpouseName).HasColumnName("father_or_spouse_name").HasMaxLength(150);vt.Property(x=>x.Gender).HasColumnName("gender").HasMaxLength(10);vt.Property(x=>x.Age).HasColumnName("age");vt.Property(x=>x.AreaName).HasColumnName("area_name").HasMaxLength(150);vt.Property(x=>x.Category).HasColumnName("category").HasMaxLength(30);vt.Property(x=>x.SlipIssued).HasColumnName("slip_issued");vt.Property(x=>x.HasVoted).HasColumnName("has_voted");vt.Property(x=>x.Phone).HasColumnName("phone").HasMaxLength(20);vt.Property(x=>x.Notes).HasColumnName("notes");vt.Property(x=>x.CreatedAtUtc).HasColumnName("created_at");

